INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('a3b03e79-58b0-4b6f-813f-b61c2e04ee3f', NULL, 'system', 'notifications.update', 'notifications', 'f052253a-569d-4790-aa51-44ef28da391f', '{"template":"Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, the parcel for order {{order_number}} is on its way back to us. Questions? Call us at {{store_phone}} or reply here.\n\nThe {{store_name}} team"}', '{}', '2026-11-03T20:03:38.735Z', '00000000-0000-4000-8000-000000000001');
