 for order {{ order.name }} did not go through. No money was taken. You can try again below.</p>⏎</td></tr>⏎{% if order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">Try again</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Order</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Items</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Total</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">To pay on delivery</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-11-03T20:03:36.310Z', '2026-11-03T20:03:38.781Z', 'Payment failed', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('1e663425-eddc-4d9c-b324-c9114a7e7c13', 'ORDER_SHIPPED', 'EMAIL', 0, 'Order {{ order.name }} is on the way', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>Your order is on the way</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">Your order is on the way</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, your order {{ order.name }} has been handed to {{ shipment.courier | default: "the courier" }}.</p>⏎{% if shipment.tracking_number %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Tracking number: <strong>{{ shipment.tracking_number }}</strong></p>{% endif %}⏎{% if order.cod_amount > 0 %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}⏎</td></tr>⏎{% if shipment.tracking_url or order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ shipment.tracking_url | default: order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">Track your parcel</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Order</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Items</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Total</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">To pay on delivery</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-11-03T20:03:36.058Z', '2026-11-03T20:03:38.781Z', 'Order shipped', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('6eaf644d-277a-4c1e-bed3-6d03456399ea', 'OUT_FOR_DELIVERY', 'EMAIL', 0, 'Order {{ order.name }} is out for delivery', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>Your order arrives today</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">Your order arrives today</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, your order {{ order.name }} is out for delivery today{% if shipment.courier %} with {{ shipment.courier }}{% endif %}.</p>⏎{% if order.cod_amount > 0 %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Please keep <strong>{{ order.cod_amount | money }}</strong> ready for the delivery person.</p>{% endif %}⏎</td></tr>⏎{% if shipment.tracking_url or order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ shipment.tracking_url | default: order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">Track your parcel</a>⏎</td></tr>{% endif %}⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-11-03T20:03:36.310Z', '2026-11-03T20:03:38.781Z', 'Out for delivery', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
